ROOT.scriptdef:
	DECLARE @NK_WalutaSystemowa int;
	SELECT @NK_WalutaSystemowa = 211;

	DECLARE @WalutaSystemowa VARCHAR(5);
	--SELECT @WalutaSystemowa = Kon_Wartosc from cdn.Konfig where Kon_Komentarz = 'Waluta systemowa';
	SELECT @WalutaSystemowa = Kon_Wartosc from cdn.Konfig where Kon_Numer = 211;
	UPDATE CDN.BudzetPrjElem
	SET BPE_Waluta = @WalutaSystemowa,
		BPE_StawkaWaluta = BPE_Stawka,
		BPE_KursL = 1,
		BPE_KursM = 1;
